import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import axios from 'axios';

const spring = { type: 'spring', stiffness: 100, damping: 10 };

/**
 * AI Executive Summary — one daily narrative paragraph generated by the backend.
 * Fetches `/api/analytics/executive-summary` and displays a typewriter-style AI blurb.
 */
export default function AIExecutiveSummary() {
    const [text, setText] = useState('');
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        axios
            .get('/api/analytics/executive-summary')
            .then((r) => setText(r.data?.summary ?? 'No summary available.'))
            .catch(() => setText('Unable to load executive summary.'))
            .finally(() => setLoading(false));
    }, []);

    return (
        <motion.div
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={spring}
            className="p-6 border bg-white dark:bg-white/5 border-gray-200 dark:border-gray-700 rounded-3xl"
        >
            <div className="flex items-center gap-2 mb-3">
                <div className="w-8 h-8 rounded-full bg-[#caff42]/20 flex items-center justify-center">
                    <svg className="w-4 h-4 text-[#caff42]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                    </svg>
                </div>
                <h3 className="text-sm font-extrabold text-gray-900 dark:text-white uppercase tracking-wider">
                    AI Executive Summary
                </h3>
            </div>

            <AnimatePresence mode="wait">
                {loading ? (
                    <motion.div
                        key="loader"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="flex items-center gap-2"
                    >
                        <div className="w-2 h-2 rounded-full bg-[#caff42] animate-pulse" />
                        <span className="text-xs text-gray-500">Generating summary…</span>
                    </motion.div>
                ) : (
                    <motion.p
                        key="text"
                        initial={{ opacity: 0, y: 8 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.5 }}
                        className="text-sm leading-relaxed text-gray-700 dark:text-gray-300"
                    >
                        {text}
                    </motion.p>
                )}
            </AnimatePresence>
        </motion.div>
    );
}
